ALTER TABLE public.motoristas ADD COLUMN ativo boolean NOT NULL DEFAULT true;
ALTER TABLE public.veiculos ADD COLUMN motorista_id uuid REFERENCES public.motoristas(id);
ALTER TABLE public.cargas_entrada ADD COLUMN veiculo_id uuid REFERENCES public.veiculos(id);
ALTER TABLE public.profiles ADD COLUMN status_acesso text NOT NULL DEFAULT 'ativo' CHECK (status_acesso IN ('ativo','pendente','inativo'));
ALTER TABLE public.profiles ADD COLUMN tipo_acesso text NOT NULL DEFAULT 'administracao' CHECK (tipo_acesso IN ('administracao','motorista'));
ALTER TABLE public.profiles ADD COLUMN telefone text;
CREATE TABLE public.login_motoristas (user_id uuid PRIMARY KEY REFERENCES public.profiles(id), cpf text NOT NULL UNIQUE CHECK(cpf ~ '^[0-9]{11}$'), email_interno text NOT NULL UNIQUE);
GRANT ALL ON public.login_motoristas TO service_role;
ALTER TABLE public.login_motoristas ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.auth_tentativas (chave text PRIMARY KEY, inicio timestamptz NOT NULL DEFAULT now(), quantidade integer NOT NULL DEFAULT 0);
GRANT ALL ON public.auth_tentativas TO service_role;
ALTER TABLE public.auth_tentativas ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.limitar_acesso(_chave text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q integer; BEGIN INSERT INTO auth_tentativas(chave,quantidade) VALUES(_chave,1) ON CONFLICT(chave) DO UPDATE SET quantidade=CASE WHEN auth_tentativas.inicio < now()-interval '15 minutes' THEN 1 ELSE auth_tentativas.quantidade+1 END, inicio=CASE WHEN auth_tentativas.inicio < now()-interval '15 minutes' THEN now() ELSE auth_tentativas.inicio END RETURNING quantidade INTO q; RETURN q<=10; END $$;
REVOKE ALL ON FUNCTION public.limitar_acesso(text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.limitar_acesso(text) TO service_role;
CREATE OR REPLACE FUNCTION private.active_user(_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM profiles WHERE id=_uid AND status_acesso='ativo') $$;
REVOKE ALL ON FUNCTION private.active_user(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION private.active_user(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION private.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM user_roles r JOIN profiles p ON p.id=r.user_id WHERE r.user_id=_user_id AND r.role=_role AND p.status_acesso='ativo') $$;
CREATE OR REPLACE FUNCTION private.can_write(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM user_roles r JOIN profiles p ON p.id=r.user_id WHERE r.user_id=_user_id AND r.role IN ('administrador','operacional') AND p.status_acesso='ativo') $$;
CREATE OR REPLACE FUNCTION private.can_finance(_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT private.can_write(_uid) OR private.has_role(_uid,'financeiro') $$;
CREATE OR REPLACE FUNCTION private.can_receive(_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT private.can_write(_uid) OR private.has_role(_uid,'conferente') $$;
REVOKE ALL ON FUNCTION private.can_finance(uuid),private.can_receive(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION private.can_finance(uuid),private.can_receive(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION private.driver_id(_uid uuid) RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT m.id FROM motoristas m WHERE m.user_id=_uid AND m.ativo AND private.has_role(_uid,'motorista') LIMIT 1 $$;
CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO profiles(id,nome,email,status_acesso) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'nome','Solicitação'),NEW.email,'pendente') ON CONFLICT(id) DO NOTHING; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.tg_profile_access() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL AND NOT private.has_role(auth.uid(),'administrador') AND (NEW.status_acesso IS DISTINCT FROM OLD.status_acesso OR NEW.tipo_acesso IS DISTINCT FROM OLD.tipo_acesso) THEN RAISE EXCEPTION 'Somente administrador altera o acesso'; END IF; RETURN NEW; END $$;
CREATE TRIGGER profile_access BEFORE UPDATE ON profiles FOR EACH ROW EXECUTE FUNCTION public.tg_profile_access();
CREATE OR REPLACE FUNCTION public.gerenciar_acesso(_user uuid,_status text,_role public.app_role,_motorista uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c text; n text; t text; m uuid; BEGIN IF NOT private.has_role(auth.uid(),'administrador') THEN RAISE EXCEPTION 'Acesso não autorizado'; END IF; IF _user=auth.uid() AND (_status<>'ativo' OR _role<>'administrador') THEN RAISE EXCEPTION 'Não altere seu próprio acesso administrativo'; END IF; SELECT nome,telefone INTO n,t FROM profiles WHERE id=_user FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Usuário não encontrado'; END IF; IF _role='motorista' THEN SELECT cpf INTO c FROM login_motoristas WHERE user_id=_user; m:=_motorista; IF m IS NULL AND c IS NOT NULL THEN SELECT id INTO m FROM motoristas WHERE regexp_replace(cpf,'\D','','g')=c LIMIT 1; END IF; IF m IS NULL THEN IF c IS NULL THEN RAISE EXCEPTION 'Escolha o cadastro do motorista'; END IF; INSERT INTO motoristas(nome,cpf,telefone,user_id) VALUES(n,c,t,_user) RETURNING id INTO m; ELSE IF EXISTS(SELECT 1 FROM motoristas WHERE id=m AND user_id IS NOT NULL AND user_id<>_user) THEN RAISE EXCEPTION 'Motorista já vinculado'; END IF; UPDATE motoristas SET user_id=NULL WHERE user_id=_user AND id<>m; UPDATE motoristas SET user_id=_user WHERE id=m; END IF; END IF; DELETE FROM user_roles WHERE user_id=_user; INSERT INTO user_roles(user_id,role) VALUES(_user,_role); UPDATE profiles SET status_acesso=_status,tipo_acesso=CASE WHEN _role='motorista' THEN 'motorista' ELSE 'administracao' END WHERE id=_user; INSERT INTO historico(entidade,entidade_id,acao,descricao,user_id) VALUES('usuario',_user,'acesso_alterado',_status||' / '||_role,auth.uid()); END $$;
REVOKE ALL ON FUNCTION public.gerenciar_acesso(uuid,text,public.app_role,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.gerenciar_acesso(uuid,text,public.app_role,uuid) TO authenticated;
CREATE POLICY finance_role_read ON public.financeiro FOR SELECT TO authenticated USING(private.can_finance(auth.uid()));
CREATE POLICY finance_notes_read ON public.notas_fiscais FOR SELECT TO authenticated USING(private.can_finance(auth.uid()));
CREATE POLICY finance_suppliers_read ON public.fornecedores FOR SELECT TO authenticated USING(private.can_finance(auth.uid()));
CREATE POLICY receive_notes_read ON public.notas_fiscais FOR SELECT TO authenticated USING(private.can_receive(auth.uid()));
CREATE POLICY receive_loads_read ON public.cargas_entrada FOR SELECT TO authenticated USING(private.can_receive(auth.uid()));
CREATE POLICY receive_checks ON public.checklists_recebimento FOR ALL TO authenticated USING(private.can_receive(auth.uid())) WITH CHECK(private.can_receive(auth.uid()));
